-- ═══════════════════════════════════════════════════════════════════════════
-- A lista do aviso aos pedidos atrasados — expedidos em 23/11/2026 (NFs de 11 a
-- 21/11), 438 pedidos, mandada pelo time em CSV (24/11/2026).
--
-- Isto é só a ENTRADA: o que o time mandou, guardado como veio (pedido da loja,
-- NF, pedido no Bling, primeiro nome, código e link do rastreio). Quem casa com
-- a esteira e carrega `carbo_msg_disparo` é o BLOCO F de
-- `supabase/consultas/aviso_pedido_atrasado.sql`, depois de alguém LER o BLOCO E
-- (não achados, ambíguos, sem telefone). Nada aqui envia mensagem.
--
-- ⚠️ Sem CPF e sem nome completo: o telefone e o resto vêm do sistema.
-- ⚠️ Lote novo = INSERT com outro `lote`; a tabela serve a qualquer disparo.
-- ═══════════════════════════════════════════════════════════════════════════

create table if not exists public.carbo_msg_disparo_entrada (
  lote            text not null,
  id_pedido_loja  text not null,
  nf              text,
  pedido_bling    text,
  primeiro_nome   text,
  codigo_rastreio text,
  link_rastreio   text,
  incluido_em     timestamptz not null default now(),
  primary key (lote, id_pedido_loja)
);

comment on table public.carbo_msg_disparo_entrada is
  'A lista CRUA de um disparo pontual, como o time mandou (lote = qual lista). O BLOCO F da consulta aviso_pedido_atrasado.sql casa com a esteira e carrega carbo_msg_disparo. Nada aqui envia.';

alter table public.carbo_msg_disparo_entrada enable row level security;
drop policy if exists carbo_msg_disparo_entrada_ler on public.carbo_msg_disparo_entrada;
create policy carbo_msg_disparo_entrada_ler on public.carbo_msg_disparo_entrada
  for select to authenticated using ((select public.carbo_e_time_interno()));
revoke all on public.carbo_msg_disparo_entrada from anon;
grant select on public.carbo_msg_disparo_entrada to authenticated;
grant all on public.carbo_msg_disparo_entrada to service_role;

insert into public.carbo_msg_disparo_entrada
  (lote, id_pedido_loja, nf, pedido_bling, primeiro_nome, codigo_rastreio, link_rastreio)
